+import { Hono } from 'hono';
+
+export const statusRoutes = new Hono();
+
+statusRoutes.patch('/:id/status', async (c) => {
+  const { status } = await c.req.json();
+  const candidate = await c.env.DB
+    .prepare('SELECT stage_id FROM candidates WHERE id = ?1')
+    .bind(c.req.param('id'))
+    .first();
+  if (!candidate) return c.json({ error: 'not_found' }, 404);
+
+  await c.env.DB
+    .prepare('UPDATE candidates SET stage_id = ?1 WHERE id = ?2')
+    .bind(status, c.req.param('id'))
+    .run();
+
+  return c.json({ success: true });
+});
